import React from "react";
import Menu from "../Menu";
import "./App.css";

const MenuApp = ({ data }) => {
  return (
    <div className="App">
      {data.map((menu) => (
        <Menu
          key={menu.menuName}
          menuName={menu.menuName}
          menuItems={menu.menuItems}
        />
      ))}
    </div>
  );
};

// Passing the data prop in the MenuApp component
MenuApp.defaultProps = {
  data: [
    {
      menuName: "Dinner",
      menuItems: [
        {
          itemId: 1,
          itemPrice: "12",
          itemName: "Lasagne",
          itemDescription:
            "Meat and cheese layered between house-made pasta with bell peppers and onions.",
        },
      ],
    },
  ],
};

export default MenuApp;
